import Base

type ProbeMode is Data:
  ProbeIdle{}
  ProbeNext{}

def invalid(mode: ProbeMode, +tokens: List<&2, Nat>) -> Nat:
  match mode tokens:
    case ProbeIdle{} value <> rest:
      invalid(ProbeNext{}, rest)
    case _ _:
      0n

def main() -> Nat:
  invalid(ProbeIdle{}, [1n])
